mapper.select:
SELECT NVL(MAX(seq_no), 0)
  FROM SJT5SG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND TR_CD   = #{trCd}

SELECT NVL(t1.TRANS_UNIT, 1000) AS "transUnit"
     , t1.TASA_FUND_CD          AS "tasaFundCd"
     , t1.FUND_NM               AS "tasaFundNm"
  FROM SJM0SC t1
 WHERE t1.CORP_GR    = #{corpGr}
   AND t1.TASA_JM_CD = #{tasaJmCd}

SELECT NVL(t1.BFIL_JWA, 0) + NVL(t1.UP_JWA, 0)   AS "trJwa"
     , NVL(t1.GBFIL_JWA, 0) + NVL(t1.GUP_JWA, 0) AS "gtrJwa"
  FROM SJM5SM t1
 WHERE t1.CORP_GR    = #{corpGr}
   AND t1.YMD        = #{ymd}
   AND t1.FUND_CD    = #{fundCd}
   AND t1.TASA_JM_CD = #{tasaJmCd}

mapper.insert:
INSERT INTO SJT5SG (
    CORP_GR
  , TR_YMD
  , TR_CD
  , FUND_CD
  , TASA_JM_CD
  , SEQ_NO
  , TR_JWA
  , GIJUNGA
  , GGIJUNGA
  , TR_AEK
  , GTR_JWA
  , TR_CO_CD
  , GIJUNGA_YMD
  , SUDO_YMD
  , UPD_JWA
  , SUSU
  , ORG_TR_YMD
  , ORG_SEQ_NO
  , TASA_SEOLJ_YMD
) VALUES (
    #{corpGr}
  , #{trYmd}
  , #{trCd}
  , #{fundCd}
  , #{tasaJmCd}
  , #{seqNo}
  , #{trJwa}
  , #{gijunga}
  , #{ggijunga}
  , #{trAek}
  , #{gtrJwa}
  , #{trCoCd}
  , #{gijungaYmd}
  , #{sudoYmd}
  , #{updJwa, jdbcType=VARCHAR}
  , #{susu, jdbcType=NUMERIC}
  , #{orgTrYmd, jdbcType=DATE}
  , #{orgSeqNo, jdbcType=NUMERIC}
  , #{tasaSeoljYmd, jdbcType=DATE}
)

mapper.update:
UPDATE SJT5SG
   SET FUND_CD        = #{fundCd}
     , TASA_JM_CD     = #{tasaJmCd}
     , TR_JWA         = #{trJwa}
     , GIJUNGA        = #{gijunga}
     , GGIJUNGA       = #{ggijunga}
     , TR_AEK         = #{trAek}
     , GTR_JWA        = #{gtrJwa}
     , TR_CO_CD       = #{trCoCd}
     , GIJUNGA_YMD    = #{gijungaYmd}
     , SUDO_YMD       = #{sudoYmd}
     , UPD_JWA        = #{updJwa, jdbcType=VARCHAR}
     , SUSU           = #{susu, jdbcType=NUMERIC}
     , ORG_TR_YMD     = #{orgTrYmd, jdbcType=DATE}
     , ORG_SEQ_NO     = #{orgSeqNo, jdbcType=NUMERIC}
     , TASA_SEOLJ_YMD = #{tasaSeoljYmd, jdbcType=DATE}
 WHERE CORP_GR        = #{corpGr}
   AND TR_YMD         = #{trYmd}
   AND TR_CD          = #{trCd}
   AND SEQ_NO         = COALESCE(#{originalSeqNo}, #{seqNo})

mapper.delete:
DELETE FROM SJT5SG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND TR_CD   = #{trCd}
   AND SEQ_NO  = COALESCE(#{originalSeqNo}, #{seqNo})
